def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    k = len(alphabet)
    char_index = {ch: i for i, ch in enumerate(alphabet)}

    transitions = [[-1] * k]
    terminal = [False]

    for word in banned:
        state = 0
        for ch in word:
            c = char_index[ch]
            if transitions[state][c] == -1:
                transitions[state][c] = len(transitions)
                transitions.append([-1] * k)
                terminal.append(False)
            state = transitions[state][c]
        terminal[state] = True

    from collections import deque

    failure = [0] * len(transitions)
    queue = deque()

    for c in range(k):
        child = transitions[0][c]
        if child == -1:
            transitions[0][c] = 0
        else:
            queue.append(child)

    while queue:
        state = queue.popleft()
        terminal[state] |= terminal[failure[state]]

        for c in range(k):
            child = transitions[state][c]
            if child == -1:
                transitions[state][c] = transitions[failure[state]][c]
            else:
                failure[child] = transitions[failure[state]][c]
                queue.append(child)

    valid_states = [state for state in range(len(transitions)) if not terminal[state]]
    index = {state: i for i, state in enumerate(valid_states)}
    size = len(valid_states)

    matrix = [[0] * size for _ in range(size)]
    for state in valid_states:
        row = matrix[index[state]]
        for target in transitions[state]:
            if not terminal[target]:
                row[index[target]] += 1

    vector = [0] * size
    vector[index[0]] = 1

    while n:
        if n & 1:
            result = [0] * size
            for i, value in enumerate(vector):
                if value:
                    for j, count in enumerate(matrix[i]):
                        if count:
                            result[j] = (result[j] + value * count) % MOD
            vector = result

        n >>= 1
        if n:
            squared = [[0] * size for _ in range(size)]
            for i in range(size):
                for j, value in enumerate(matrix[i]):
                    if value:
                        for t, count in enumerate(matrix[j]):
                            if count:
                                squared[i][t] = (
                                    squared[i][t] + value * count
                                ) % MOD
            matrix = squared

    return sum(vector) % MOD
